def backfill_tienda_cliente(apps, schema_editor):
    """Las Venta con origen_mp_suscripcion=True creadas ANTES de este campo
    solo tenían cliente_nombre/cliente_cuit (texto, para la factura) -- se
    completa tienda_cliente ahora matcheando primero por CUIT (más confiable,
    no cambia) y si no hay CUIT o no matchea, por nombre exacto. Best-effort:
    lo que no matchee queda en null (ej. tienda ya borrada tras cancelación +
    30 días), no rompe nada, solo no entra en los totales por tienda nuevos."""
    Venta = apps.get_model('inventario', 'Venta')
    Tienda = apps.get_model('inventario', 'Tienda')

    tiendas_por_cuit = {t.cuit: t for t in Tienda.objects.exclude(cuit__isnull=True).exclude(cuit='')}
    tiendas_por_nombre = {t.nombre: t for t in Tienda.objects.all()}

    pendientes = Venta.objects.filter(origen_mp_suscripcion=True, tienda_cliente__isnull=True)
    actualizadas = 0
    for venta in pendientes:
        tienda = tiendas_por_cuit.get(venta.cliente_cuit) if venta.cliente_cuit else None
        if tienda is None and venta.cliente_nombre:
            tienda = tiendas_por_nombre.get(venta.cliente_nombre)
        if tienda is not None:
            venta.tienda_cliente = tienda
            venta.save(update_fields=['tienda_cliente'])
            actualizadas += 1

    if actualizadas:
        print(f"  backfill_tienda_cliente: {actualizadas} venta(s) de suscripción vinculada(s) a su tienda.")


